package app.kivo.store;
import android.content.pm.*;import android.os.Build;import org.json.*;import java.io.*;import java.net.*;import java.security.*;import java.util.*;import java.util.regex.*;import java.util.zip.*;
/** Inspects public game metadata and uses the user's own itch authorization for uploads. */
final class ItchGames {
 final MainActivity host;volatile boolean running;final Map<Long,JSONObject> checked=new java.util.concurrent.ConcurrentHashMap<>();
 ItchGames(MainActivity h){host=h;}
 String token()throws Exception{String t=host.itchAuth.read("itchToken");if(t.isEmpty())throw new IOException("Conecta tu cuenta de itch.io en Tu espacio.");return t;}
 long gameId(String raw)throws Exception{URL u=new URL(raw);String h=u.getHost().toLowerCase(Locale.ROOT);if(!u.getProtocol().equals("https")||!h.endsWith(".itch.io")||u.getPort()!=-1||u.getUserInfo()!=null)throw new IOException("Página de itch.io no válida.");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(9000);c.setReadTimeout(12000);try{if(c.getResponseCode()!=200)throw new IOException("No se pudo leer la página del juego.");String html;try(InputStream in=c.getInputStream()){html=MainActivity.read(in,2*1024*1024);}Matcher m=Pattern.compile("data-game_id=[\\\"']([0-9]{1,12})[\\\"']").matcher(html);Set<String> ids=new HashSet<>();while(m.find())ids.add(m.group(1));if(ids.size()!=1)throw new IOException("No se pudo identificar este juego con certeza.");return Long.parseLong(ids.iterator().next());}finally{c.disconnect();}}
 JSONObject inspect(JSONObject feed,int index,String t)throws Exception{long id=gameId(feed.getString("link"));JSONObject response=new JSONObject(host.itchAuth.request("https://api.itch.io/games/"+id+"/uploads","GET",null,t));JSONArray uploads=response.optJSONArray("uploads");if(uploads==null||response.has("errors"))throw new IOException("Itch.io no devolvió los archivos.");JSONArray apks=new JSONArray();for(int i=0;i<uploads.length();i++){JSONObject u=uploads.optJSONObject(i);if(u==null)continue;String name=u.optString("filename");long size=u.optLong("size"),upload=u.optLong("id");if(name.toLowerCase(Locale.ROOT).endsWith(".apk")&&upload>0&&size>0&&size<=500L*1024*1024&&!u.optBoolean("preorder"))apks.put(new JSONObject().put("id",upload).put("name",name).put("size",size));}return new JSONObject().put("gameId",id).put("index",index).put("name",feed.optString("plainTitle")).put("link",feed.optString("link")).put("description",feed.optString("description")).put("assets",apks);}
 void open(int index){host.searches.execute(()->{try{JSONObject game=inspect(host.itchItems.getJSONObject(index),index,token());checked.put(game.getLong("gameId"),game);publish();if(game.getJSONArray("assets").length()>0)host.send("itchOpenDetail",game.getLong("gameId"));else host.new Bridge().openItchItem(index,true,false);}catch(Exception e){host.status("No se pudo comprobar el APK: "+e.getMessage());}});}
 void scan(){if(running)return;running=true;host.send("itchScanState","loading");host.searches.execute(()->{int errors=0;try{String t=token();JSONArray feed=host.itchItems;for(int i=0;i<Math.min(feed.length(),40);i++){try{JSONObject game=inspect(feed.getJSONObject(i),i,t);checked.put(game.getLong("gameId"),game);publish();}catch(Exception e){errors++;}}host.send("itchScanState",errors>0?"partial":"ready");}catch(Exception e){host.status(e.getMessage());host.send("itchScanState","error");}finally{running=false;}});}
 void publish(){JSONArray a=new JSONArray();for(JSONObject game:checked.values())if(game.optJSONArray("assets")!=null&&game.optJSONArray("assets").length()>0)a.put(game);host.send("itchApks",a);}
 void download(long gameId,long uploadId){host.transfers.execute(()->{File tmp=null;try{JSONObject game=checked.get(gameId);if(game==null)throw new IOException("Vuelve a comprobar el juego.");JSONObject asset=null;JSONArray list=game.getJSONArray("assets");for(int i=0;i<list.length();i++)if(list.getJSONObject(i).optLong("id")==uploadId)asset=list.getJSONObject(i);if(asset==null)throw new IOException("El archivo ya no está disponible.");String t=token();host.status("Preparando descarga de itch.io…");JSONObject session=new JSONObject(host.itchAuth.request("https://api.itch.io/games/"+gameId+"/download-sessions","POST","",t));String uuid=session.getString("uuid");URL u=new URL("https://api.itch.io/uploads/"+uploadId+"/download?uuid="+URLEncoder.encode(uuid,"UTF-8"));File dir=new File(host.getFilesDir(),"apks");dir.mkdirs();tmp=File.createTempFile("itch-",".tmp",dir);MessageDigest digest=MessageDigest.getInstance("SHA-256");long total=0;for(int redirects=0;redirects<6;redirects++){if(!u.getProtocol().equals("https")||u.getUserInfo()!=null||u.getPort()!=-1)throw new IOException("Destino de descarga no válido.");String h=u.getHost().toLowerCase(Locale.ROOT);boolean api=h.equals("api.itch.io");if(!api&&!h.endsWith(".itch.zone")&&!h.endsWith(".itch.io"))throw new IOException("Itch.io devolvió un servidor de descarga no admitido.");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(30000);if(api)c.setRequestProperty("Authorization","Bearer "+t);try{int code=c.getResponseCode();if(code>=300&&code<400){String loc=c.getHeaderField("Location");if(loc==null)throw new IOException("Falta el destino de descarga.");u=new URL(u,loc);continue;}if(code!=200)throw new IOException("Itch.io respondió HTTP "+code);String mime=c.getContentType();if(mime!=null&&mime.toLowerCase(Locale.ROOT).contains("json")){String json;try(InputStream in=c.getInputStream()){json=MainActivity.read(in,262144);}String link=new JSONObject(json).optString("url");if(link.isEmpty())throw new IOException("Itch.io no devolvió un enlace de descarga.");u=new URL(link);continue;}try(InputStream in=c.getInputStream();OutputStream out=new FileOutputStream(tmp)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1){total+=n;if(total>500L*1024*1024)throw new IOException("APK demasiado grande.");digest.update(b,0,n);out.write(b,0,n);}}break;}finally{c.disconnect();}}if(total!=asset.getLong("size"))throw new IOException("Descarga incompleta o tamaño distinto al publicado.");PackageManager pm=host.getPackageManager();int flags=Build.VERSION.SDK_INT>=28?PackageManager.GET_SIGNING_CERTIFICATES:PackageManager.GET_SIGNATURES;PackageInfo apk=pm.getPackageArchiveInfo(tmp.getPath(),flags);if(apk==null||apk.applicationInfo==null)throw new IOException("El archivo no es un APK válido.");if(apk.applicationInfo.minSdkVersion>Build.VERSION.SDK_INT)throw new IOException("El juego necesita una versión más reciente de Android.");String sign=host.signers(apk);try{PackageInfo installed=pm.getPackageInfo(apk.packageName,flags);if(!host.signers(installed).equals(sign))throw new IOException("La firma no coincide con la app instalada.");if(MainActivity.code(installed)>=MainActivity.code(apk))throw new IOException("Ya tienes esta versión o una más reciente.");}catch(PackageManager.NameNotFoundException ignored){}Set<String> abis=new HashSet<>();try(ZipFile zip=new ZipFile(tmp)){Enumeration<? extends ZipEntry> files=zip.entries();while(files.hasMoreElements()){String n=files.nextElement().getName();if(n.startsWith("lib/")&&n.endsWith(".so")){String[] parts=n.split("/");if(parts.length>2)abis.add(parts[1]);}}}if(!abis.isEmpty()&&Collections.disjoint(abis,Arrays.asList(Build.SUPPORTED_ABIS)))throw new IOException("El APK no es compatible con la arquitectura del celular.");File finalFile=new File(dir,MainActivity.hex(digest.digest())+".apk");if(finalFile.exists())tmp.delete();else if(!tmp.renameTo(finalFile))throw new IOException("No se pudo guardar el APK.");tmp=null;host.pending=finalFile;host.runOnUiThread(()->host.installPending());host.status("APK descargado. Confirma la instalación en Android.");}catch(Exception e){host.status("No se pudo descargar el juego: "+(e.getMessage()==null?"inténtalo de nuevo.":e.getMessage()));}finally{if(tmp!=null)tmp.delete();}});}
}
